parameters.jsCode:
const content = $('Content_writer').item.json.output.trim();
const hashtags = String($('Hastag').item.json.output || '')
  .split(/\s+/).filter(t => t.startsWith('#')).join(' ');
const imageUrl = $('Img1').item.json.data.url;
const edited = String($input.first().json.Content || '').trim();

return [{
  json: {
    image_url: imageUrl,
    caption: (edited || `${content}\n\n${hashtags}`).replace(/\\n/g, '\n')
  }
}];

for (const item of $input.all()) {
  item.binary.data.fileName = 'poster.jpg';
  item.binary.data.mimeType = 'image/jpeg';
}
return $input.all();

// Mon/Wed/Fri posting.  Language alternates every post: English, Tamil, English, Tamil ...
// Poster type is fixed per weekday: Mon = mobile, Wed = laptop, Fri = web
// => all 6 posters (mobile/laptop/web x English/Tamil) come out in every 2 weeks.
const OFFSET = 1;   // 1 => Monday 12 Oct 2026 = English. If your first post comes out in the other language, change 1 to 0

const now = $now;   // workflow timezone
const days = Math.floor(Date.UTC(now.year, now.month - 1, now.day) / 86400000);
const weekIndex = Math.floor((days + 3) / 7);              // weeks start on Monday
const slot = ({ 1: 0, 3: 1, 5: 2 })[now.weekday] ?? 0;    // Mon=0, Wed=1, Fri=2
const idx = weekIndex * 3 + slot + OFFSET;                 // post number

const language = idx % 2 === 0 ? 'English' : 'Tamil';
const layout = ['mobile', 'laptop', 'web'][slot];

return [{
  json: {
    ...$json,
    language,
    variant: `${layout}_${language.toLowerCase()}`,
    languageInstruction: language === 'Tamil'
      ? 'Write the entire caption in Tamil (தமிழ்) script only. Keep brand and technical words (OMNERA, EMI, Field Agents) in English. Length: between 115 and 135 words. Never write fewer than 110 words.'
      : 'Write the entire caption in English only. Length: between 115 and 135 words. Never write fewer than 110 words.',
    hashtagInstruction: language === 'Tamil'
      ? 'Give 10 hashtags: 7 English and 3 Tamil.'
      : 'Give 10 English hashtags.'
  }
}];
